SELECT id, staff_no, name, gender, phone, department, duty, status, entry_date, remark FROM maintainer
AND ( staff_no LIKE CONCAT('%', #{keyword}, '%') OR name LIKE CONCAT('%', #{keyword}, '%') OR phone LIKE CONCAT('%', #{keyword}, '%') OR duty LIKE CONCAT('%', #{keyword}, '%') OR remark LIKE CONCAT('%', #{keyword}, '%') )
AND department = #{department}
AND status = #{status}
ORDER BY id ASC

SELECT id, staff_no, name, gender, phone, department, duty, status, entry_date, remark
FROM maintainer
WHERE id = #{id}
